      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Where there were several studies with similar exposure definitions, data were included in a random effects meta-analysis for the respective exposure and CKDu and displayed in a forest plot.",
      "reason": "The manuscript describes grouping studies for synthesis based on similar exposure definitions for meta-analysis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There were no notable restrictions on study eligibility that required a specific rationale beyond standard systematic review criteria."
    }
  ],
  "confidence": 95
}

